begin;

with input_items as (
  select *
  from jsonb_to_recordset($seed_json$[]$seed_json$::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    aliases text[],
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.aliases, '{}'::text[]) as aliases,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, aliases, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset($seed_json$[{"id": "329c68a8-c090-5b4b-a92b-0b4f4b72e711", "feature_slug": "web-page-copy", "title": "Web Page Copy — Overview", "content": "**When to use:** Routing parent only — read Which part to use before fetching a part slug. Do not load all four parts at once.\n**Source:** `WEB_PAGE_COPY_PRINCIPLES.md`\n**Genre:** `web`\n\nLanding pages, blog articles, SEO, and internal linking", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md", "metadata": {"genre": "web", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "overview", "feature_slug": "web-page-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "63145af38cdbda2a2fc2769f820d4e39eb715cc1d6380dff8a70bc34f91229d3", "truncated": false}, "is_active": true}, {"id": "541ddee2-05ff-5933-a43d-4bb5c39a5a0e", "feature_slug": "web-page-copy", "title": "Which part to use", "content": "| Page type | Primary part | Also read |\n|-----------|--------------|-----------|\n| Product landing page | **Part 1** — Landing Page Copy | Part 3 (SEO signals), Part 4 (links in/out) |\n| Blog / knowledge article | **Part 2** — Blog & Knowledge Articles | Part 3, Part 4 |\n| SEO planning / on-page audit | **Part 3** — SEO Strategy | Part 1 or 2 depending on page type |\n| Link architecture / new article workflow | **Part 4** — Internal Linking | Part 3 (clusters, intent tiers) |\n\n---", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#which-part-to-use", "metadata": {"genre": "web", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "which-part-to-use", "feature_slug": "web-page-copy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b8b5104129c8fd1b94ae60f4585ea649e3f08cd194730149e1b8f0df60f6d145", "truncated": false}, "is_active": true}, {"id": "b10911ad-a31a-5b0f-b17e-1af60fe15fb8", "feature_slug": "web-seo-strategy", "title": "PART 1: The Two-Page Model", "content": "SEO for B2B SaaS = owning the entire search journey with two page types that feed each other.\n\nA buyer searches dozens of times before purchasing: problem queries, category queries, comparison queries, brand queries. Each intent deserves a different page. The system:\n\n- **Landing pages** — capture high-intent searches, convert them\n- **Knowledge/blog pages** — capture early/mid-funnel searches, build authority, push qualified readers toward landing pages\n\nNeither works at full capacity alone. Knowledge pages earn authority and warm traffic. Landing pages convert it. The connection between them is the strategy.\n\n**The funnel:**\n```\nReader searches a question → Knowledge page ranks, answers it\n    → Reader trusts the brand → Internal link → Landing page\n    → Reader is warm + educated → Conversion\n```\n\nCold traffic on a landing page closes at a lower rate than warm traffic from a knowledge page that taught them something first. The knowledge page is the pre-sale.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-1-the-two-page-model", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-1-the-two-page-model", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "df0db1efd0fff05b6e4089cfc3b32070bac67bceea476e4da9b8e84e6450b575", "truncated": false}, "is_active": true}, {"id": "3c8b7409-392f-5244-bbd0-9b7aa619711f", "feature_slug": "web-seo-strategy", "title": "PART 2: Keyword Strategy", "content": "### 1. Intent Tier Mapping\n\nBuild separate pages for each intent tier:\n\n| Tier | Keyword type | Example | Page type |\n|---|---|---|---|\n| **T1: Category** | What the product IS | \"loyalty CRM,\" \"ระบบสะสมแต้ม\" | Landing page |\n| **T2: Use case** | What it does for a segment | \"loyalty program สำหรับ ecommerce\" | Landing page |\n| **T3: Feature** | A specific capability | \"ระบบแลกคะแนนออนไลน์,\" \"AI churn prediction\" | Landing page |\n| **T4: Comparison** | Evaluating options | \"Rocket vs. [competitor],\" \"loyalty CRM เปรียบเทียบ\" | Landing or knowledge |\n| **T5: Pricing** | Checking budget fit | \"loyalty CRM ราคา,\" \"ราคาระบบสะสมแต้ม\" | Landing page |\n| **T6: Informational** | Learning about the category | \"loyalty program คืออะไร,\" \"วิธีสร้าง Loyalty Program\" | Knowledge page |\n| **T7: Investigational** | Evaluating approaches | \"เลือก loyalty CRM อย่างไร,\" \"Points vs. Tier\" | Knowledge page |\n\nEach tier = a different page. Never rank one page for all tiers.\n\n### 2. Search Volume vs. Intent Quality\n\nHigh volume ≠ best target. A 500/month keyword with buyer intent outperforms a 5,000/month keyword where most searchers are students or competitors.\n\nEvaluate on three factors:\n1. **Search volume** — traffic ceiling\n2. **Intent signal** — % of searchers who are buyers\n3. **Ranking difficulty** — SERP competitiveness\n\nFor early-stage B2B SaaS: target medium-volume, high-intent keywords first. They convert faster and rank easier.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-2-keyword-strategy", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-2-keyword-strategy", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "21d8e7bac5d25ba3948c6112e6afb17cca77db95aceb2c082859697f27e9b710", "truncated": false}, "is_active": true}, {"id": "39f2f52a-e101-598b-bafb-8340150ff704", "feature_slug": "web-seo-strategy", "title": "PART 3: Landing Pages — Rank + Convert", "content": "A landing page's primary job is conversion (form fill, demo, trial). Its secondary job is ranking for a high-intent keyword. It exists for one keyword and one action — not a blog, not a category guide.\n\nOn-page SEO signals (keyword placement, semantic completeness) shared with knowledge pages are consolidated in Part 5.\n\n### 3. Keyword-Intent Match\n\nThe page must match what the searcher expected. If they typed \"ระบบสะสมแต้ม SME\" they expect pricing, ease of setup, and a demo — not an enterprise pitch with custom quotes only.\n\nMatch four dimensions:\n1. **Type** — product page, not a guide\n2. **Format** — comparison, features, pricing, or demo\n3. **Angle** — SME vs. enterprise, fast setup vs. full customization\n4. **Stage** — evaluating, not learning — remove educational padding\n\nMismatched pages produce high bounce rates → signals poor quality to Google AND kills conversions.\n\n### 4. Hero Section: 5-Second Rule\n\nThe reader must know what it is and who it's for in 5 seconds.\n\n**H1 formula:** `[Keyword] + [Identity or Differentiator]`\n- \"ระบบสะสมแต้ม สำหรับแบรนด์ B2C ที่ต้องการสร้าง Loyalty Program จริงจัง\"\n- \"Loyalty CRM ที่รวม Points, Tiers, และ AI ไว้ในระบบเดียว\"\n\nThe subhead adds specificity the H1 leaves out. H1 = claim, subhead = proof-in-one-line.\n\n**What kills the hero:** generic tagline (\"The Future of Loyalty\"), company history, screenshot with no context, CTA before the reader knows what they're looking at.\n\n### 5. Page Structure\n\n```\n1. Hero — what + who + primary CTA\n2. Social proof bar — logos, hard numbers (before features)\n3. Problem statement — name the pain\n4. Features/capabilities — prove you solve it\n5. Differentiators — why you, not a competitor\n6. Deeper proof — case studies, testimonials, metrics\n7. Objection FAQ — handle blockers before the form\n8. 3-step plan — reduce perceived complexity\n9. Final CTA — shortest, punchiest section\n```\n\nSocial proof must come before features. The reader must trust you before you sell.\n\n### 6. CTA Discipline\n\nOne primary action per page. Same CTA in four positions: hero, after social proof, after differentiators, close. No competing CTAs (demo vs. trial vs. pricing vs. download).\n\n**CTA copy rule:** Outcome + speed/ease. Nothing else.\n- \"นัด Demo ฟรี — เห็นระบบทำงานจริงใน 30 นาที\"\n- \"ทดลองใช้ฟรี 14 วัน ไม่ต้องใช้บัตรเครดิต\"\n\n### 7. FAQ as Objection Killer\n\nB2B prospects have real blockers before submitting a form:\n- \"ใช้ยาก / ต้องใช้ Developer ไหม?\"\n- \"เชื่อมต่อกับระบบที่ใช้อยู่ได้ไหม?\"\n- \"ราคาเท่าไหร่ / มีแพ็กเกจอะไรบ้าง?\"\n- \"ข้อมูลลูกค้าปลอดภัยไหม?\"\n- \"Support ช่วยตั้งค่าได้ไหม?\"\n\nAnswer on-page. A reader whose blocker dissolves converts. One who has to contact you often doesn't. Bonus: FAQPage schema turns these into rich results (see section 17).\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-3-landing-pages-rank-convert", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-3-landing-pages-rank-convert", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "14fb54ed583283db46fa9ec46c440d97cd57279120c5c795bb15eb0d0649033c", "truncated": false}, "is_active": true}, {"id": "545587ca-f836-55eb-a69b-1891e9fd2657", "feature_slug": "web-seo-strategy", "title": "PART 4: Knowledge Pages — Rank + Feed", "content": "A knowledge page answers a question a target buyer is already asking — before they're ready to buy.\n\nIts jobs, in order:\n1. Rank for the question keyword\n2. Build topical authority that lifts the whole site\n3. Educate the reader until the landing page CTA makes sense\n4. Link to landing pages — transfer authority and qualified traffic\n\nKnowledge pages teach. They don't sell. Product mentions appear only after earning the right by solving the reader's problem. For linking strategy from knowledge pages to landing pages, see Part 6.\n\n### 8. Keyword Types for Knowledge Pages\n\n**Informational** — \"What is X?\" / \"How does X work?\"\n- \"loyalty program คืออะไร\"\n- \"วิธีสร้าง Loyalty Program สำหรับร้านค้า\"\n- \"ระบบสมาชิกออนไลน์ทำงานอย่างไร\"\n- \"churn คืออะไร วิธีลด churn ใน ecommerce\"\n\n**Investigational** — \"Which is better?\" / \"What should I look for?\"\n- \"เลือก loyalty CRM อย่างไร\"\n- \"loyalty program vs. discount strategy\"\n- \"ฟีเจอร์ที่ loyalty platform ที่ดีต้องมี\"\n\nThese searchers aren't ready to buy, but will be. Own their question now and your brand enters their consideration set before they search with buying intent.\n\n### 9. Content Depth and Original Value\n\nThin content that summarizes what already ranks will not outrank it.\n\nWhat earns rankings:\n- **Original data** — platform statistics, benchmarks, customer outcomes\n- **Specific examples** — real use cases, before/after scenarios, case studies\n- **Practical frameworks** — step-by-step processes the reader can use immediately\n- **Honest comparison** — acknowledge trade-offs, not just advantages\n- **Expert perspective** — analysis a generalist couldn't write\n\nThe test: would someone who read the top 3 ranking articles find something new, useful, and non-obvious here? If not, rewrite.\n\n### 10. Article Structure for SEO\n\n**Title (H1):** Contains primary keyword. Answers the reader's question. Clear, not clever.\n- \"Loyalty Program คืออะไร และทำไมแบรนด์ B2C ถึงต้องมี\"\n- \"วิธีลด Churn Rate ด้วย Loyalty Program: 6 กลยุทธ์ที่ได้ผล\"\n\n**Introduction (first 150 words):** Keyword in first 100 words. States what the article covers and who it's for. BLUF — don't bury the answer.\n\n**H2s:** Each H2 = a logical subtopic a reader would search for. H2s that mirror natural question phrasing rank for sub-queries. Every major section has its own H2; every subsection an H3.\n\n**Conclusion:** Key takeaways + natural transition to next step (landing page link or CTA).\n\n### 11. Word Count Heuristics\n\nNo magic number. Long enough to fully answer, short enough to prevent bounce.\n\n- Definitional (\"what is X\"): 800–1,500 words\n- How-to guides: 1,200–2,500 words\n- Comprehensive pillar guides: 2,500–5,000+ words\n- Comparison articles: 1,500–3,000 words\n\nPadding to hit a word count is the most common SEO mistake. Cut ruthlessly.\n\n### 12. Content Type Map\n\n| Type | Example | Primary job | Links to |\n|---|---|---|---|\n| **Definition** | \"Loyalty Program คืออะไร\" | Top-of-funnel, establish authority | Pillar + category LP |\n| **How-to** | \"วิธีสร้าง Loyalty Program สำหรับ ecommerce\" | Mid-funnel, practical value | Feature LPs |\n| **Comparison** | \"Points-based vs. Tier-based Loyalty\" | Investigational queries | Category LP |\n| **Vertical** | \"Loyalty Program สำหรับแบรนด์ FMCG\" | Segment-specific searches | Segment LP |\n| **Benchmark** | \"Retention Rate ที่ดี ควรเป็นเท่าไหร่\" | Authority with original data | Analytics feature |\n| **Best practice** | \"10 วิธีเพิ่ม Loyalty Engagement\" | Broad reach, shareability | Multiple feature pages |\n| **Alternative** | \"Rocket vs. [Competitor]\" | Evaluation-stage | Main LP |\n| **Case study** | \"แบรนด์แฟชั่นเพิ่ม Retention 40%\" | Credibility with proof | Demo CTA |\n\n### 13. Soft CTAs in Knowledge Content\n\n**Placement logic:**\n- **Top:** \"ถ้าคุณกำลังมองหาระบบ Loyalty CRM — [ดูแพลตฟอร์ม Rocket]\" — catches readers who already know\n- **Mid-page:** inline contextual link when describing a relevant capability\n- **Bottom:** harder CTA — \"พร้อมสร้าง Loyalty Program จริงจัง? [นัด Demo ฟรี]\"\n\nThe bottom CTA can mirror the landing page CTA — by then the reader has been educated and is warmer.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-4-knowledge-pages-rank-feed", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-4-knowledge-pages-rank-feed", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "fca760c207b59502da12562220e7a8c6c273ccfe6dcd2bc5bca28d99ad1ff936", "truncated": false}, "is_active": true}, {"id": "012f23a6-e651-5ddd-9a10-453f47f1f922", "feature_slug": "web-seo-strategy", "title": "PART 5: On-Page SEO Signals", "content": "These apply to both landing pages and knowledge pages. For page-type-specific structure and content rules, see Parts 3–4.\n\n### 14. Keyword Placement (Non-Negotiable)\n\n| Signal | Requirement |\n|---|---|\n| **Title tag** | Keyword appears. Under 60 chars |\n| **Meta description** | Keyword once. Benefit + CTA. Under 155 chars |\n| **H1** | Keyword appears. One H1 per page |\n| **First 100 words** | Keyword appears naturally |\n| **At least one H2** | Keyword or close variant (LPs: ≥1; knowledge pages: ≥2–3) |\n| **URL slug** | Keyword-based, hyphenated, short. `/loyalty-crm/` not `/page-about-our-loyalty-crm-platform/` |\n| **Image alt text** | At least one references the keyword |\n\nEvery signal missed is a relevance point lost.\n\n### 15. Semantic Completeness\n\nGoogle evaluates topic coverage, not just keyword presence. A \"ระบบสะสมแต้ม\" page should naturally contain:\n- Related terms: สมาชิก, แต้ม, รางวัล, Loyalty Program, แคมเปญ, ระดับสมาชิก\n- Use cases: ร้านค้า, แบรนด์ B2C, Omnichannel, ออนไลน์/ออฟไลน์\n- Outcomes: ซื้อซ้ำ, Retention, Churn, ยอดขาย\n\nWrite comprehensively and these terms appear naturally. Don't keyword-stuff.\n\n### 16. E-E-A-T Signals\n\nGoogle evaluates Experience, Expertise, Authoritativeness, Trustworthiness:\n\n| Signal | How |\n|---|---|\n| **Experience** | Real product data, customer outcomes, screenshots, specific numbers |\n| **Expertise** | Author bio with credentials; depth a generalist couldn't achieve |\n| **Authoritativeness** | External links from industry publications, partner sites, directories |\n| **Trustworthiness** | Accurate claims, no exaggeration, linked sources, publish/update dates |\n\nFor AI-assisted content: every factual claim must be verified by a human with domain expertise. Google's systems detect whether real experience touched the content.\n\n### 17. Structured Data\n\nFor B2B SaaS pages:\n- **SoftwareApplication schema** — tells Google this is a software product (landing pages)\n- **FAQPage schema** — FAQ sections appear as rich results, expanding search real estate (both page types)\n- **Organization schema** — reinforces brand identity (site-wide)\n\nNot a ranking shortcut. A visibility amplifier.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-5-on-page-seo-signals", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-5-on-page-seo-signals", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "d0fb99b3081635f940367455de8e3c950a36e08e426c2e040822bf5c20931202", "truncated": false}, "is_active": true}, {"id": "3fedfe1d-fe07-5cf4-80da-f56985107d6e", "feature_slug": "web-seo-strategy", "title": "PART 6: Linking & Authority", "content": "On-page SEO has a ceiling. Links break through it — both internal (structure) and external (authority).\n\n### 18. Topic Clusters\n\nGoogle rewards sites with deep, interconnected expertise — not one good page surrounded by unrelated content.\n\n**Structure:**\n- **Pillar page** — comprehensive guide on the core topic (\"คู่มือ Loyalty Program สำหรับ B2C\")\n- **Cluster pages** — shorter articles on subtopics (\"วิธีออกแบบ Tier System,\" \"ตัวอย่าง Loyalty ที่ได้ผล\")\n- **Landing pages** — the commercial pages the cluster links toward\n\nPillar links to all cluster pages. Clusters link back to pillar. Both link to relevant landing pages. This web tells Google: this site owns this topic.\n\n### 19. Contextual Internal Links\n\nEvery knowledge page: 1–3 contextual links to relevant landing pages. Also include landing pages in site navigation or category pages — not just contextual article links.\n\n**Rules:**\n- Link when the reader has reason to want more detail on a capability\n- Descriptive anchor text — \"ระบบสะสมแต้ม Omnichannel\" not \"คลิกที่นี่\"\n- Place at the moment intent shifts from learning to considering\n- Too early = interruption. Too late = reader already left\n\n**The transition moment:** after explaining a problem or best practice, the reader thinks \"I need a tool that does this.\" That's where the link goes.\n\n> \"...ระบบที่ดีจะรวมคะแนนจากทุกช่องทางเป็นโปรไฟล์ลูกค้าเดียวอัตโนมัติ — ดูว่า [Rocket Loyalty CRM] ทำแบบนี้ได้อย่างไร\"\n\n### 20. PageRank Flow\n\nInternal links pass authority. A well-ranking knowledge page with strong backlinks transfers that authority to landing pages through internal links.\n\n**Build intentionally:**\n1. Earn backlinks to high-quality knowledge pages (outreach, guest posts, being cited as a source)\n2. Knowledge page links to landing page\n3. Landing page inherits authority\n\nA link from a page ranking on page 1 for a competitive keyword is worth more than 20 links from obscure pages.\n\n### 21. Site Authority and Backlinks\n\nWithout external sites linking to yours, high-competition keywords are unwinnable.\n\n**Backlink sources for B2B SaaS in Thai market:**\n- Industry publications (Thumbsup, Marketeeronline, Brand Buffet)\n- Technology and startup media\n- Partner integrations (Shopify app marketplace, LINE Official listing, platform directories)\n- Guest content on sites your buyers read\n- Awards and ranking lists (\"Best CRM platforms in Thailand\")\n- Being cited in category guides by comparison sites\n\nQuality > quantity. One link from a high-authority, relevant site outweighs 100 from irrelevant directories.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-6-linking-authority", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-6-linking-authority", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "8ac4f6a87ce7036ea5cbd4a854b1a334d0417b199992f6bd997883f8555636bd", "truncated": false}, "is_active": true}, {"id": "857b3c1f-e112-5752-af94-872f9220e31b", "feature_slug": "web-seo-strategy", "title": "PART 7: Technical SEO", "content": "Technical foundations both page types require. Without these, on-page and linking efforts are wasted.\n\n### 22. Page Speed and Core Web Vitals\n\nGoogle uses page experience as a ranking signal:\n- **LCP (Largest Contentful Paint):** under 2.5s. Hero image is usually the culprit — compress it.\n- **CLS (Cumulative Layout Shift):** under 0.1. No font/image shifts after load.\n- **FID/INP:** under 200ms. Interactive elements respond fast.\n\nMobile performance matters even for B2B. Decision-makers research on mobile.\n\n### 23. Mobile-First Indexing\n\nGoogle indexes mobile-first. Design and test mobile before desktop:\n- Hero sections that truncate on mobile\n- Navigation hiding important links in hamburger menus\n- CTAs too small or too close together on a phone screen\n- Tables that overflow horizontally\n\n### 24. Crawlability and Indexation\n\nGoogle can only rank pages it can find:\n- **XML sitemap** — submitted and updated. Include all landing pages and key articles.\n- **robots.txt** — landing pages and articles not blocked\n- **Canonical tags** — every page declares its canonical URL to prevent duplicate content\n- **No orphan pages** — every important page reachable from at least one other page\n\n### 25. URL Structure\n\nURLs are a ranking signal and trust signal:\n- Descriptive, keyword-based slugs: `/loyalty-crm/` not `/p?id=4821`\n- Hyphens between words, not underscores\n- Short as possible while descriptive\n- Language separation: `/th/loyalty-crm/` not `?lang=th`\n- Knowledge pages under logical parent: `/blog/loyalty-program-คืออะไร/`\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-7-technical-seo", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-7-technical-seo", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "4f526b70c0f71a408ddcb4ff656b59ed95b186e8e4ba9f5c0cf2c4200502ed35", "truncated": false}, "is_active": true}, {"id": "e4c80424-62f1-580f-8055-b03498562a84", "feature_slug": "web-seo-strategy", "title": "PART 8: The Flywheel", "content": "SEO compounds:\n\n```\nMore quality content → more pages ranking → more authority signals\n    → higher rankings across all pages → more traffic → more leads\n    → more customers → more case studies → more proof on-page\n    → higher conversion → business grows → invest in more content\n    → (repeat)\n```\n\nThis is a 12–18 month investment before it feels like a moat. The compounding starts slow. It doesn't stop.\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#part-8-the-flywheel", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "part-8-the-flywheel", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "0df5c1eee96aba75a3e36cc1bcff285de9e4c54df30cc3fbe37a589c610e5e4a", "truncated": false}, "is_active": true}, {"id": "68ad0e2e-bf49-538e-98c2-54800bb196f7", "feature_slug": "web-seo-strategy", "title": "Quick Reference: Landing Page vs. Knowledge Page", "content": "| | Landing Page | Knowledge Page |\n|---|---|---|\n| **Primary job** | Convert high-intent traffic | Rank for questions + build authority |\n| **Secondary job** | Rank for category/feature keywords | Feed warm traffic to landing pages |\n| **Keyword intent** | Transactional / commercial | Informational / investigational |\n| **Content** | Focused — feature + proof + CTA | Comprehensive — full answer |\n| **CTA** | Hard — demo, trial, pricing | Soft → hard at bottom |\n| **Links out** | Minimal — keep attention on conversion | 1–3 links to relevant landing pages |\n| **Success metric** | Conversion rate + ranking | Rankings + traffic + LP click-through |\n| **Update trigger** | Product or pricing changes | Search intent shifts or new data |\n\n---\n\n---", "content_format": "markdown", "knowledge_type": "rules", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md#quick-reference-landing-page-vs-knowledge-page", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "quick-reference-landing-page-vs-knowledge-page", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "b303780ba45d03646976081234662a21f88cf08c1b7030fb10633d218f9dfbbf", "truncated": false}, "is_active": true}, {"id": "0f0e3543-5e8f-5624-ae46-6911bdc6e9ad", "feature_slug": "web-seo-strategy", "title": "Web — SEO Strategy — Overview", "content": "**When to use:** SEO strategy for landing and knowledge pages. Intent tiers T1–T7, on-page signals, technical SEO, flywheel.\n**Source:** `WEB_PAGE_COPY_PRINCIPLES.md` (Part 3)\n**Genre:** `seo`\n\nPart 3 — SEO Strategy & On-Page Signals Applies to landing pages and knowledge/blog pages", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/WEB_PAGE_COPY_PRINCIPLES.md", "metadata": {"genre": "seo", "source_file": "WEB_PAGE_COPY_PRINCIPLES.md", "section_anchor": "overview", "part": 3, "feature_slug": "web-seo-strategy", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "ba555bde4d01e2ce780464ce11f7e8283ab2fe64d64fea8f4df8d06cd007d6ca", "truncated": false}, "is_active": true}, {"id": "2e2a007d-0ef2-5375-82d1-aaf5e6796e64", "feature_slug": "writing-principles", "title": "Writing Principles MCP — How To Use", "content": "## Universal foundation\n\nAlways fetch core-writing before any genre-specific playbook. Core principles apply to every structured writing task.\n\n## Truth boundary\n\nWriting MCP = craft and structure. CRM Knowledge MCP = Rocket product facts. Compose both for proposals, decks, and feature guides that mention platform capabilities.\n\n## Default tool sequence\n\n1. `writing_get_my_context`\n2. `writing_get_core_principles`\n3. `writing_resolve_genre (if genre unclear)`\n4. `writing_search_guidance (natural-language question)`\n5. `writing_get_playbook_context (deterministic blocks for resolved slug)`\n\n## Task → playbook composition\n\n### Cold email, blog post, landing page, SEO page\n- **Playbooks:** core-writing → genre slug → translation (if localized)\n- **Tools:** writing_get_core_principles, writing_search_guidance, writing_get_playbook_context\n\n### Rocket B2B proposal / RFP response\n- **Playbooks:** core-writing → proposal-writing → CRM search_semantic for feature facts\n- **Tools:** writing_get_playbook_context(proposal-writing), CRM get_feature_answer_context\n\n### Sales or marketing deck\n- **Playbooks:** core-writing → sales-slides → CRM get_feature_context (if feature-specific slides)\n- **Tools:** writing_get_playbook_context(sales-slides), CRM get_feature_context\n\n### Thai / JP / TW localized copy\n- **Playbooks:** core-writing → genre slug → translation\n- **Tools:** writing_get_core_principles, writing_get_playbook_context, writing_get_playbook_context(translation)\n\n### CRM feature guide\n- **Playbooks:** core-writing → feature-guide-writing → CRM get_feature_context for the feature slug\n- **Tools:** writing_get_playbook_context(feature-guide-writing), CRM get_feature_context\n\n### Web content — pick the right part first\n- **Playbooks:** core-writing → web-page-copy routing overview → one of web-landing-copy | web-article-copy | web-seo-strategy | web-internal-linking\n- **Tools:** writing_get_playbook_context(web-page-copy), writing_get_playbook_context(part slug)", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "sales"], "output_uses": ["agent_context", "marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "Writing Principles/INDEX.md#mcp-retrieval-protocol", "metadata": {"section_anchor": "mcp-retrieval-protocol", "doc_role": "mcp_onboarding", "feature_slug": "writing-principles", "generation_batch": "writing_principles_seed_20260530T011413Z", "content_sha256": "c092aa62962e48a30b7ed9f9510ba1a8c4d8c2ab70d2da3a38904799dfbbbbb5", "truncated": false}, "is_active": true}]$seed_json$::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
